<?php
require_once __DIR__.'/../../includes/accounting_ui.php';
$id=(int)($_GET['id']??0);try{$credit=$ac->record('ac_credits',$id);}catch(InvalidArgumentException $e){denySchoolRequest($e->getMessage(),404);}
acHandle(function()use($ac,$id){if(($_POST['action']??'')!=='refund')throw new InvalidArgumentException('Choose a supported credit action.');return $ac->refundCredit(array_replace($_POST,['credit_id'=>$id]));},'credit',['id'=>$id]);
$document=$ac->invoiceDocument((int)$credit['invoice_id']);$invoice=$document['invoice'];$schoolInfo=$document['school'];
$items=$ac->rows('SELECT ci.*,i.particular FROM ac_credit_items ci JOIN ac_invoice_items i ON i.id=ci.invoice_item_id AND i.invoice_id=? WHERE ci.school_id=? AND ci.credit_id=? ORDER BY ci.id',[$invoice['id'],$school,$id]);
$refunds=$ac->rows('SELECT r.*,a.name account_name FROM ac_credit_refunds r JOIN ac_accounts a ON a.id=r.account_id AND a.school_id=r.school_id WHERE r.school_id=? AND r.credit_id=? ORDER BY r.id',[$school,$id]);$refunded=0;foreach($refunds as $refund)$refunded=acCheckedAdd($refunded,(int)$refund['amount_minor']);$remaining=(int)$credit['refund_minor']-$refunded;
ob_start();
?>
<div class="d-flex gap-2 mb-3 no-print"><button class="btn btn-primary" data-erp-click="accounting-credit-action-0" data-erp-click-args="<?= schoolPageActionArgs("accounting-credit",[]) ?>">Print / Save as PDF</button><a class="btn btn-outline-secondary" href="<?= acUrl('invoice',['id'=>$invoice['id']]) ?>">Original invoice</a></div>
<article class="ac-document"><header class="ac-document-header"><?php if(!empty($schoolInfo['logo'])): ?><img src="<?= APP_URL ?>/uploads/<?= rawurlencode(basename($schoolInfo['logo'])) ?>" alt="School logo"><?php endif; ?><div><h2><?= sanitize($schoolInfo['name_en']) ?></h2><p><?= sanitize($schoolInfo['address']??'') ?><br><?= sanitize(($schoolInfo['phone']??'').' · '.($schoolInfo['email']??'')) ?></p><?php if($document['pan_number']): ?><small>PAN / tax registration: <?= sanitize($document['pan_number']) ?></small><?php endif; ?></div></header>
<h3>CREDIT NOTE <?= sanitize($credit['number']) ?></h3><p>Original invoice: <?= sanitize($invoice['number']) ?><br>Customer: <?= sanitize($invoice['customer_name']) ?> <?= sanitize($document['student']['student_id']??'') ?><br><?= sanitize($document['class']['name']??'') ?><br>Credit date: <?= sanitize(schoolDateLabel($credit['credit_date'],'both','ymd')) ?><br>Reason: <?= sanitize($credit['reason']) ?></p>
<table><thead><tr><th>SN</th><th>Particular</th><th class="money">Credit incl. tax</th><th class="money">Tax reversed</th></tr></thead><tbody><?php foreach($items as $n=>$item): ?><tr><td><?= $n+1 ?></td><td><?= sanitize($item['particular']) ?></td><td class="money"><?= acMoney((int)$item['amount_minor']) ?></td><td class="money"><?= acMoney((int)$item['tax_minor']) ?></td></tr><?php endforeach; ?><?php if(!$items): ?><tr><td>1</td><td>Verified opening correction / historical credit</td><td class="money"><?= acMoney((int)$credit['amount_minor']) ?></td><td class="money"><?= acMoney((int)$credit['tax_minor']) ?></td></tr><?php endif; ?></tbody></table>
<div class="summary"><?php foreach(['Total credit'=>'amount_minor','Tax reversed'=>'tax_minor','Reduction of unpaid dues'=>'receivable_minor','Approved refund payable'=>'refund_minor'] as $label=>$field): ?><p><span><?= $label ?></span><strong><?= acMoney((int)$credit[$field]) ?></strong></p><?php endforeach; ?><p><span>Refund paid</span><strong><?= acMoney($refunded) ?></strong></p><p><span>Refund remaining</span><strong><?= acMoney($remaining) ?></strong></p></div><p><?= sanitize(acWords((int)$credit['amount_minor'])) ?></p><p>The original bill is preserved. This credit is not a cash receipt.</p><footer class="mt-5"><?= printUserSignature($db,(int)$school,(int)$credit['created_by'],'Authorized by') ?></footer></article>
<?php if($refunds): ?><div class="card card-body table-responsive mt-3"><h4>Approved refund history</h4><table class="table"><thead><tr><th>Refund</th><th>Date (BS / AD)</th><th>Account</th><th>Amount</th><th>Reason</th></tr></thead><tbody><?php foreach($refunds as $r): ?><tr><td><?= sanitize($r['number']) ?></td><td><?= sanitize(schoolDateLabel($r['refund_date'],'both','ymd')) ?></td><td><?= sanitize($r['account_name']) ?></td><td><?= acMoney((int)$r['amount_minor']) ?></td><td><?= sanitize($r['reason']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<?php if($remaining>0&&$ac->can('refund')): ?><details class="no-print mt-3"><summary>Approve payment of remaining credit refund</summary><?php acForm('refund');acInput('amount','Refund amount (NPR)',acAmount($remaining),'number');acInput('date','Refund date',date('Y-m-d'),'date');acInput('reason','Refund reason / supporting reference');acSelect('account_id','Cash / bank account',$ac->rows("SELECT * FROM ac_accounts WHERE school_id=? AND is_active=1 AND type='asset' AND cash_bank_kind IN ('cash','bank') AND (control_key IS NULL OR control_key IN ('cash','bank')) ORDER BY code",[$school])); ?><div class="alert alert-warning">This records an approved payout against this credit only. It does not initiate a bank transfer or payment gateway refund.</div><label><input type="checkbox" name="confirm" value="1" required> I verified and authorize this refund; original payments must not also be reversed.</label><?php acSubmit('Approve credit refund'); ?></details><?php endif; ?>
<?php acRender('Credit note & refund',ob_get_clean());
